/* Reset some default styles to ensure consistency across browsers */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

/* Apply basic styles to the body */
body {
  font-family: 'Lato', sans-serif;
  font-size: 16px;
  line-height: 1.5;
}

/* Set styles for headings */
h1, h2, h3, h4, h5, h6 {
  margin: 1rem 0;
  font-weight: bold;

}

/* Set styles for links */
a {
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

/* Set styles for paragraphs */
p {
  margin: 0 0 1rem;
}

/* Set styles for lists */
ul, ol {
  margin: 0 0 1rem;
  padding: 0;
}

li {
  margin: 0.5rem 0;
}

/* Set styles for blockquotes */
blockquote {
  margin: 1rem 0;
  padding: 0.5rem;

}

/* Set styles for spans */
span {
  font-style: normal;
}

/* Set styles for buttons */
button {
  padding: 0.5rem 1rem;
  border: none;
  border-radius: 3px;
  cursor: pointer;
}

/* Set styles for images */
img {
  max-width: 100%;
  height: auto;
}

/* Set styles for videos */
video {
  max-width: 100%;
}

/* Set styles for audios */
audio {
  display: block;
  width: 100%;
}

/* Set styles for forms */
form {
  margin-bottom: 1rem;
}

label {
  display: block;
  margin-bottom: 0.5rem;
  font-weight: bold;
}

input,
textarea,
select {
  padding: 0.5rem;
  border-radius: 3px;
}

input[type="file"],
input[type="color"] {
  padding: 0;
}

input[type="submit"] {
  padding: 0.5rem 1rem;
  color: #ffffff;
  border: none;
  border-radius: 3px;
  cursor: pointer;
}

input[type="submit"]:hover {
  background-color: #cc0000;
}
